'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isBetween = require( '@stdlib/assert/is-between' );
var isMethod = require( '@stdlib/assert/is-method' );
var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var isInteger = require( '@stdlib/assert/is-integer' ).isPrimitive;
var isPositiveInteger = require( '@stdlib/assert/is-positive-integer' ).isPrimitive;
var isUint32Array = require( '@stdlib/assert/is-uint32array' );
var Uint32Array = require( '@stdlib/array/uint32' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var pcg32 = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof pcg32, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the main export is a `normalized` method', function test( t ) {
	t.strictEqual( isMethod( pcg32, 'normalized' ), true, 'returns expected value' );
	t.end();
});

tape( 'attached to the main export is a `factory` method', function test( t ) {
	t.strictEqual( isMethod( pcg32, 'factory' ), true, 'returns expected value' );
	t.end();
});

tape( 'attached to the main export is a `toJSON` method', function test( t ) {
	t.strictEqual( isMethod( pcg32, 'toJSON' ), true, 'returns expected value' );
	t.end();
});

tape( 'attached to the main export is a read-only `NAME` property', function test( t ) {
	t.strictEqual( hasOwnProp( pcg32, 'NAME' ), true, 'returns expected value' );
	t.strictEqual( pcg32.NAME, 'pcg32', 'returns expected value' );
	t.throws( foo, Error, 'throws an error' );
	t.end();

	function foo() {
		pcg32.NAME = 'foo';
	}
});

