tape( 'the function returns pseudorandom integers strictly between 0 and 2^32-1 (inclusive)', function test( t ) {
	var v;
	var i;
	for ( i = 0; i < 1e3; i++ ) {
		v = pcg32();
		t.strictEqual( isInteger( v ), true, 'returns expected value' );
		t.strictEqual( isBetween( v, 0, UINT32_MAX ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the `normalized` method returns pseudorandom numbers strictly between 0 (inclusive) and 1 (exclusive)', function test( t ) {
	var v;
	var i;
	for ( i = 0; i < 1e3; i++ ) {
		v = pcg32.normalized();
		t.strictEqual( isNumber( v ), true, 'returns expected value' );
		t.strictEqual( isBetween( v, 0.0, 1.0, 'closed', 'open' ), true, 'returns expected value' );
	}
	t.end();
});

