tape( 'the generator supports setting the generator state', function test( t ) {
	var state;
	var arr;
	var i;

	// Move to a future state...
	for ( i = 0; i < 100; i++ ) {
		pcg32();
	}
	// Capture the current state:
	state = pcg32.state;

	// Move to a future state...
	arr = [];
	for ( i = 0; i < 100; i++ ) {
		arr.push( pcg32() );
	}
	// Set the state:
	pcg32.state = state;

	// Replay previously generated values...
	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( pcg32(), arr[ i ], 'returns expected value' );
	}
	t.end();
});

